// Generated by esquadro: do not edit. A record's picture: its image, or,
// without one (or while it fails to load), the first letters of its name.
import { useEffect, useState } from "react"
import { cn } from "@/lib/utils"
import type { Rec } from "./meta.ts"
import type { Resource } from "./resource.ts"

/** The first letters of what a record is called: "Webcam HD" is WH. */
export function initials(text: string): string {
  const words = text.trim().split(/\s+/).filter(Boolean)
  return ((words[0]?.[0] ?? "") + (words[1]?.[0] ?? "")).toLocaleUpperCase() || "#"
}

const SIZES = {
  sm: "size-10 rounded-lg text-xs",
  lg: "size-20 rounded-2xl text-2xl",
}

export function Picture({
  src,
  name,
  size = "sm",
  className,
}: {
  src?: string | null
  name: string
  size?: keyof typeof SIZES
  className?: string
}) {
  const [failed, setFailed] = useState(false)
  useEffect(() => setFailed(false), [src])
  const box = cn("flex shrink-0 items-center justify-center overflow-hidden", SIZES[size], className)
  if (src && !failed) {
    return (
      <span className={cn(box, "border border-border bg-muted")}>
        <img src={src} alt="" loading="lazy" className="size-full object-cover" onError={() => setFailed(true)} />
      </span>
    )
  }
  return (
    <span className={cn(box, "bg-primary/10 font-bold text-primary")} aria-hidden>
      {initials(name)}
    </span>
  )
}

/**
 * A record's picture: the resource's image, or else its first image
 * field's file; none when it has neither.
 */
export function imageOf(resource: Resource, record: Rec): string | null | undefined {
  const own = resource.image?.(record)
  if (own) return own
  const field = Object.values(resource.meta.fields).find((f) => f.kind === "image")
  const file = field && (record[field.name] as { url?: string } | null | undefined)
  return file?.url
}
